B.acq=s(["Hair Bonds & Care","\u982d\u9aee\u9375\u7d50\u8207\u8b77\u7406"],t.s)
B.a3T=s(["Bonds, care and color design","\u9375\u7d50\u3001\u8b77\u7406\u8207\u8272\u5f69\u8a2d\u8a08"],t.s)
