B.Z1=s(["Your first look at CMY and color","\u521d\u8b58 CMY \u8207\u8272\u5f69\u89c0\u5bdf"],t.s)
B.a5q=s(["The Science of Light & Color","\u5149\u8207\u8272\u5f69\u79d1\u5b78"],t.s)
B.a79=s(["Visible light, reflection and primary colors","\u53ef\u898b\u5149\u3001\u53cd\u5c04\u8207\u4e09\u539f\u8272"],t.s)
B.a4i=s(["Applied Color Perception","\u8272\u5f69\u8996\u89ba\u61c9\u7528"],t.s)
