B.abe=s(["Lightness & Undertones","\u660e\u5ea6\u8207\u5e95\u8272"],t.s)
B.U5=s(["Levels, lightening and residual pigment","\u8272\u5ea6\u3001\u812b\u8272\u8207\u6b98\u7559\u8272\u7d20"],t.s)
B.Z_=s(["Hair Growth & Structure","\u982d\u9aee\u751f\u9577\u8207\u7d50\u69cb"],t.s)
B.Z3=s(["Hair cycle, cuticle and pH","\u6bdb\u9aee\u9031\u671f\u3001\u6bdb\u9c57\u7247\u8207 pH"],t.s)
